mkitem!{mktrait!{# [doc = " An annotation for an SCC. This can be a representative,"] # [doc = " the max/min element of the SCC, or all of the above."] # [doc = ""] # [doc = " Concretely, the both merge operations must commute, e.g. where `merge`"] # [doc = " is `merge_scc` and `merge_reached`: `a.merge(b) == b.merge(a)`"] # [doc = ""] # [doc = " In general, what you want is probably always min/max according"] # [doc = " to some ordering, potentially with side constraints (min x such"] # [doc = " that P holds)."] pub trait Annotation : Debug + Copy { # [doc = " Merge two existing annotations into one during"] # [doc = " path compression.o"] fn merge_scc (self , other : Self) -> Self ; # [doc = " Merge a successor into this annotation."] fn merge_reached (self , other : Self) -> Self ; fn update_scc (& mut self , other : Self) { * self = self . merge_scc (other) } fn update_reachable (& mut self , other : Self) { * self = self . merge_reached (other) } }}}
mkitem!{mktrait!{# [doc = " An accumulator for annotations."] pub trait Annotations < N : Idx > { type Ann : Annotation ; type SccIdx : Idx + Ord ; fn new (& self , element : N) -> Self :: Ann ; fn annotate_scc (& mut self , scc : Self :: SccIdx , annotation : Self :: Ann) ; }}}
mkitem!{mkstruct!{# [doc = " The nil annotation accumulator, which does nothing."] struct NoAnnotations < S : Idx + Ord > (PhantomData < S >) ;}}
mkitem!{mkimpl!{impl < N : Idx , S : Idx + Ord > Annotations < N > for NoAnnotations < S > { type SccIdx = S ; type Ann = () ; fn new (& self , _element : N) { } fn annotate_scc (& mut self , _scc : S , _annotation : ()) { } }}}
mkitem!{mkimpl!{# [doc = " The empty annotation, which does nothing."] impl Annotation for () { fn merge_reached (self , _other : Self) -> Self { () } fn merge_scc (self , _other : Self) -> Self { () } }}}
mkitem!{mkstruct!{# [doc = " Strongly connected components (SCC) of a graph. The type `N` is"] # [doc = " the index type for the graph nodes and `S` is the index type for"] # [doc = " the SCCs. We can map from each node to the SCC that it"] # [doc = " participates in, and we also have the successors of each SCC."] pub struct Sccs < N : Idx , S : Idx > { # [doc = " For each node, what is the SCC index of the SCC to which it"] # [doc = " belongs."] scc_indices : IndexVec < N , S > , # [doc = " Data about all the SCCs."] scc_data : SccData < S > , }}}
mkitem!{mkstruct!{# [doc = " Information about an invidividual SCC node."] struct SccDetails { # [doc = " For this SCC, the range of `all_successors` where its"] # [doc = " successors can be found."] range : Range < usize > , }}}
mkitem!{mkstruct!{struct SccData < S : Idx > { # [doc = " Maps SCC indices to their metadata, including"] # [doc = " offsets into `all_successors`."] scc_details : IndexVec < S , SccDetails > , # [doc = " Contains the successors for all the Sccs, concatenated. The"] # [doc = " range of indices corresponding to a given SCC is found in its"] # [doc = " `scc_details.range`."] all_successors : Vec < S > , }}}
mkitem!{mkimpl!{impl < N : Idx , S : Idx + Ord > Sccs < N , S > { # [doc = " Compute SCCs without annotations."] pub fn new (graph : & impl Successors < Node = N >) -> Self { Self :: new_with_annotation (graph , & mut NoAnnotations (PhantomData :: < S >)) } # [doc = " Compute SCCs and annotate them with a user-supplied annotation"] pub fn new_with_annotation < A : Annotations < N , SccIdx = S > > (graph : & impl Successors < Node = N > , annotations : & mut A ,) -> Self { SccsConstruction :: construct (graph , annotations) } pub fn scc_indices (& self) -> & IndexSlice < N , S > { & self . scc_indices } # [doc = " Returns the number of SCCs in the graph."] pub fn num_sccs (& self) -> usize { self . scc_data . len () } # [doc = " Returns an iterator over the SCCs in the graph."] # [doc = ""] # [doc = " The SCCs will be iterated in **dependency order** (or **post order**),"] # [doc = " meaning that if `S1 -> S2`, we will visit `S2` first and `S1` after."] # [doc = " This is convenient when the edges represent dependencies: when you visit"] # [doc = " `S1`, the value for `S2` will already have been computed."] pub fn all_sccs (& self) -> impl Iterator < Item = S > + 'static { (0 .. self . scc_data . len ()) . map (S :: new) } # [doc = " Returns the SCC to which a node `r` belongs."] pub fn scc (& self , r : N) -> S { self . scc_indices [r] } # [doc = " Returns the successors of the given SCC."] pub fn successors (& self , scc : S) -> & [S] { self . scc_data . successors (scc) } # [doc = " Construct the reverse graph of the SCC graph."] pub fn reverse (& self) -> VecGraph < S > { VecGraph :: new (self . num_sccs () , self . all_sccs () . flat_map (| source | { self . successors (source) . iter () . map (move | & target | (target , source)) }) . collect () ,) } }}}
mkitem!{mkimpl!{impl < N : Idx , S : Idx + Ord > DirectedGraph for Sccs < N , S > { type Node = S ; fn num_nodes (& self) -> usize { self . num_sccs () } }}}
mkitem!{mkimpl!{impl < N : Idx , S : Idx + Ord > NumEdges for Sccs < N , S > { fn num_edges (& self) -> usize { self . scc_data . all_successors . len () } }}}
mkitem!{mkimpl!{impl < N : Idx , S : Idx + Ord > Successors for Sccs < N , S > { fn successors (& self , node : S) -> impl Iterator < Item = Self :: Node > { self . successors (node) . iter () . cloned () } }}}
mkitem!{mkimpl!{impl < S : Idx > SccData < S > { # [doc = " Number of SCCs,"] fn len (& self) -> usize { self . scc_details . len () } # [doc = " Returns the successors of the given SCC."] fn successors (& self , scc : S) -> & [S] { & self . all_successors [self . scc_details [scc] . range . clone ()] } # [doc = " Creates a new SCC with `successors` as its successors and"] # [doc = " returns the resulting index."] fn create_scc (& mut self , successors : impl IntoIterator < Item = S >) -> S { let all_successors_start = self . all_successors . len () ; self . all_successors . extend (successors) ; let all_successors_end = self . all_successors . len () ; debug ! ("create_scc({:?}) successors={:?}" , self . len () , & self . all_successors [all_successors_start .. all_successors_end] ,) ; let range = all_successors_start .. all_successors_end ; let metadata = SccDetails { range } ; self . scc_details . push (metadata) } }}}
mkitem!{mkstruct!{struct SccsConstruction < 'c , 'a , G , A > where G : DirectedGraph + Successors , A : Annotations < G :: Node > , { graph : & 'c G , # [doc = " The state of each node; used during walk to record the stack"] # [doc = " and after walk to record what cycle each node ended up being"] # [doc = " in."] node_states : IndexVec < G :: Node , NodeState < G :: Node , A :: SccIdx , A :: Ann > > , # [doc = " The stack of nodes that we are visiting as part of the DFS."] node_stack : Vec < G :: Node > , # [doc = " The stack of successors: as we visit a node, we mark our"] # [doc = " position in this stack, and when we encounter a successor SCC,"] # [doc = " we push it on the stack. When we complete an SCC, we can pop"] # [doc = " everything off the stack that was found along the way."] successors_stack : Vec < A :: SccIdx > , # [doc = " A set used to strip duplicates. As we accumulate successors"] # [doc = " into the successors_stack, we sometimes get duplicate entries."] # [doc = " We use this set to remove those -- we also keep its storage"] # [doc = " around between successors to amortize memory allocation costs."] duplicate_set : FxHashSet < A :: SccIdx > , scc_data : SccData < A :: SccIdx > , annotations : & 'a mut A , }}}
mkitem!{mkenum!{# [derive (Copy , Clone , Debug)] enum NodeState < N , S , A : Annotation > { # [doc = " This node has not yet been visited as part of the DFS."] # [doc = ""] # [doc = " After SCC construction is complete, this state ought to be"] # [doc = " impossible."] NotVisited , # [doc = " This node is currently being walked as part of our DFS. It is on"] # [doc = " the stack at the depth `depth` and its current annotation is"] # [doc = " `annotation`."] # [doc = ""] # [doc = " After SCC construction is complete, this state ought to be"] # [doc = " impossible."] BeingVisited { depth : usize , annotation : A } , # [doc = " Indicates that this node is a member of the given cycle where"] # [doc = " the merged annotation is `annotation`."] # [doc = " Note that an SCC can have several cycles, so its final annotation"] # [doc = " is the merged value of all its member annotations."] InCycle { scc_index : S , annotation : A } , # [doc = " Indicates that this node is a member of whatever cycle"] # [doc = " `parent` is a member of. This state is transient: whenever we"] # [doc = " see it, we try to overwrite it with the current state of"] # [doc = " `parent` (this is the \"path compression\" step of a union-find"] # [doc = " algorithm)."] InCycleWith { parent : N } , }}}
mkitem!{mkenum!{# [doc = " The state of walking a given node."] # [derive (Copy , Clone , Debug)] enum WalkReturn < S , A : Annotation > { # [doc = " The walk found a cycle, but the entire component is not known to have"] # [doc = " been fully walked yet. We only know the minimum depth of  this"] # [doc = " component in a minimum spanning tree of the graph. This component"] # [doc = " is tentatively represented by the state of the first node of this"] # [doc = " cycle we met, which is at `min_depth`."] Cycle { min_depth : usize , annotation : A } , # [doc = " The SCC and everything reachable from it have been fully walked."] # [doc = " At this point we know what is inside the SCC as we have visited every"] # [doc = " node reachable from it. The SCC can now be fully represented by its ID."] Complete { scc_index : S , annotation : A } , }}}
mkitem!{mkimpl!{impl < 'c , 'a , G , A > SccsConstruction < 'c , 'a , G , A > where G : DirectedGraph + Successors , A : Annotations < G :: Node > , { # [doc = " Identifies SCCs in the graph `G` and computes the resulting"] # [doc = " DAG. This uses a variant of [Tarjan's"] # [doc = " algorithm][wikipedia]. The high-level summary of the algorithm"] # [doc = " is that we do a depth-first search. Along the way, we keep a"] # [doc = " stack of each node whose successors are being visited. We"] # [doc = " track the depth of each node on this stack (there is no depth"] # [doc = " if the node is not on the stack). When we find that some node"] # [doc = " N with depth D can reach some other node N' with lower depth"] # [doc = " D' (i.e., D' < D), we know that N, N', and all nodes in"] # [doc = " between them on the stack are part of an SCC."] # [doc = ""] # [doc = " Additionally, we keep track of a current annotation of the SCC."] # [doc = ""] # [doc = " [wikipedia]: https://bit.ly/2EZIx84"] fn construct (graph : & 'c G , annotations : & 'a mut A) -> Sccs < G :: Node , A :: SccIdx > { let num_nodes = graph . num_nodes () ; let mut this = Self { graph , node_states : IndexVec :: from_elem_n (NodeState :: NotVisited , num_nodes) , node_stack : Vec :: with_capacity (num_nodes) , successors_stack : Vec :: new () , scc_data : SccData { scc_details : IndexVec :: new () , all_successors : Vec :: new () } , duplicate_set : FxHashSet :: default () , annotations , } ; let scc_indices = graph . iter_nodes () . map (| node | match this . start_walk_from (node) { WalkReturn :: Complete { scc_index , .. } => scc_index , WalkReturn :: Cycle { min_depth , .. } => { panic ! ("`start_walk_node({node:?})` returned cycle with depth {min_depth:?}") } }) . collect () ; Sccs { scc_indices , scc_data : this . scc_data } } fn start_walk_from (& mut self , node : G :: Node) -> WalkReturn < A :: SccIdx , A :: Ann > { self . inspect_node (node) . unwrap_or_else (| | self . walk_unvisited_node (node)) } # [doc = " Inspect a node during the DFS. We first examine its current"] # [doc = " state -- if it is not yet visited (`NotVisited`), return `None` so"] # [doc = " that the caller might push it onto the stack and start walking its"] # [doc = " successors."] # [doc = ""] # [doc = " If it is already on the DFS stack it will be in the state"] # [doc = " `BeingVisited`. In that case, we have found a cycle and we"] # [doc = " return the depth from the stack."] # [doc = ""] # [doc = " Otherwise, we are looking at a node that has already been"] # [doc = " completely visited. We therefore return `WalkReturn::Complete`"] # [doc = " with its associated SCC index."] fn inspect_node (& mut self , node : G :: Node) -> Option < WalkReturn < A :: SccIdx , A :: Ann > > { Some (match self . find_state (node) { NodeState :: InCycle { scc_index , annotation } => { WalkReturn :: Complete { scc_index , annotation } } NodeState :: BeingVisited { depth : min_depth , annotation } => { WalkReturn :: Cycle { min_depth , annotation } } NodeState :: NotVisited => return None , NodeState :: InCycleWith { parent } => panic ! ("`find_state` returned `InCycleWith({parent:?})`, which ought to be impossible") , }) } # [doc = " Fetches the state of the node `r`. If `r` is recorded as being"] # [doc = " in a cycle with some other node `r2`, then fetches the state"] # [doc = " of `r2` (and updates `r` to reflect current result). This is"] # [doc = " basically the \"find\" part of a standard union-find algorithm"] # [doc = " (with path compression)."] fn find_state (& mut self , mut node : G :: Node) -> NodeState < G :: Node , A :: SccIdx , A :: Ann > { let mut previous_node = node ; let (root_state , assigned_state) = { loop { trace ! ("find_state(r = {node:?} in state {:?})" , self . node_states [node]) ; match self . node_states [node] { s @ NodeState :: NotVisited => return s , s @ NodeState :: InCycle { .. } => break (s , s) , s @ NodeState :: BeingVisited { depth , .. } => { break (s , NodeState :: InCycleWith { parent : self . node_stack [depth] }) ; } NodeState :: InCycleWith { parent } => { assert ! (node != parent , "Node can not be in cycle with itself") ; self . node_states [node] = NodeState :: InCycleWith { parent : previous_node } ; previous_node = node ; node = parent ; } } } } ; loop { if previous_node == node { return root_state ; } trace ! ("Compressing {node:?} down to {previous_node:?} with state {assigned_state:?}") ; match self . node_states [previous_node] { NodeState :: InCycleWith { parent : previous } => { node = previous_node ; previous_node = previous ; } other => unreachable ! ("Invalid previous link while compressing cycle: {other:?}") , } self . node_states [node] = assigned_state ; } } # [doc = " Walks a node that has never been visited before."] # [doc = ""] # [doc = " Call this method when `inspect_node` has returned `None`. Having the"] # [doc = " caller decide avoids mutual recursion between the two methods and allows"] # [doc = " us to maintain an allocated stack for nodes on the path between calls."] # [instrument (skip (self , initial) , level = "trace")] fn walk_unvisited_node (& mut self , initial : G :: Node) -> WalkReturn < A :: SccIdx , A :: Ann > { trace ! ("Walk unvisited node: {initial:?}") ; struct VisitingNodeFrame < G : DirectedGraph , Successors , A > { node : G :: Node , successors : Option < Successors > , depth : usize , min_depth : usize , successors_len : usize , min_cycle_root : G :: Node , successor_node : G :: Node , # [doc = " The annotation for the SCC starting in `node`. It may or may"] # [doc = " not contain other nodes."] current_component_annotation : A , } let mut successors_stack = core :: mem :: take (& mut self . successors_stack) ; debug_assert_eq ! (successors_stack . len () , 0) ; let mut stack : Vec < VisitingNodeFrame < G , _ , _ > > = vec ! [VisitingNodeFrame { node : initial , depth : 0 , min_depth : 0 , successors : None , successors_len : 0 , min_cycle_root : initial , successor_node : initial , current_component_annotation : self . annotations . new (initial) , }] ; let mut return_value = None ; 'recurse : while let Some (frame) = stack . last_mut () { let VisitingNodeFrame { node , depth , successors , successors_len , min_depth , min_cycle_root , successor_node , current_component_annotation , } = frame ; let node = * node ; let depth = * depth ; trace ! ("Visiting {node:?} at depth {depth:?}, annotation: {current_component_annotation:?}") ; let successors = match successors { Some (successors) => successors , None => { trace ! (? depth , ? node) ; debug_assert_matches ! (self . node_states [node] , NodeState :: NotVisited) ; self . node_states [node] = NodeState :: BeingVisited { depth , annotation : * current_component_annotation , } ; self . node_stack . push (node) ; * successors_len = successors_stack . len () ; successors . get_or_insert (self . graph . successors (node)) } } ; let successors_len = * successors_len ; let returned_walk = return_value . take () . into_iter () . map (| walk | (* successor_node , Some (walk))) ; let successor_walk = successors . map (| successor_node | { trace ! (? node , ? successor_node) ; (successor_node , self . inspect_node (successor_node)) }) ; for (successor_node , walk) in returned_walk . chain (successor_walk) { match walk { Some (WalkReturn :: Cycle { min_depth : successor_min_depth , annotation : successor_annotation , }) => { trace ! ("Cycle found from {node:?}, minimum depth: {successor_min_depth:?}, annotation: {successor_annotation:?}") ; assert ! (successor_min_depth <= depth) ; if successor_min_depth < * min_depth { trace ! (? node , ? successor_min_depth) ; * min_depth = successor_min_depth ; * min_cycle_root = successor_node ; } current_component_annotation . update_scc (successor_annotation) ; } Some (WalkReturn :: Complete { scc_index : successor_scc_index , annotation : successor_annotation , }) => { trace ! ("Complete; {node:?} is root of complete-visited SCC idx {successor_scc_index:?} with annotation {successor_annotation:?}") ; trace ! (? node , ? successor_scc_index) ; successors_stack . push (successor_scc_index) ; current_component_annotation . update_reachable (successor_annotation) ; } None => { let depth = depth + 1 ; trace ! ("Recursing down into {successor_node:?} at depth {depth:?}") ; trace ! (? depth , ? successor_node) ; frame . successor_node = successor_node ; stack . push (VisitingNodeFrame { node : successor_node , depth , successors : None , successors_len : 0 , min_depth : depth , min_cycle_root : successor_node , successor_node , current_component_annotation : self . annotations . new (successor_node) , }) ; continue 'recurse ; } } } trace ! ("Finished walk from {node:?} with annotation: {current_component_annotation:?}") ; let r = self . node_stack . pop () ; debug_assert_eq ! (r , Some (node)) ; let frame = stack . pop () . unwrap () ; let current_component_annotation = frame . current_component_annotation ; debug_assert_eq ! (frame . node , node) ; debug_assert ! (return_value . is_none ()) ; return_value = Some (if frame . min_depth == depth { let deduplicated_successors = { let duplicate_set = & mut self . duplicate_set ; duplicate_set . clear () ; successors_stack . drain (successors_len ..) . filter (move | & i | duplicate_set . insert (i)) } ; debug ! ("Creating SCC rooted in {node:?} with successor {:?}" , frame . successor_node) ; let scc_index = self . scc_data . create_scc (deduplicated_successors) ; self . annotations . annotate_scc (scc_index , current_component_annotation) ; self . node_states [node] = NodeState :: InCycle { scc_index , annotation : current_component_annotation } ; WalkReturn :: Complete { scc_index , annotation : current_component_annotation } } else { self . node_states [node] = NodeState :: InCycleWith { parent : frame . min_cycle_root } ; WalkReturn :: Cycle { min_depth : frame . min_depth , annotation : current_component_annotation , } }) ; } self . successors_stack = successors_stack ; debug_assert_eq ! (self . successors_stack . len () , 0) ; return_value . unwrap () } }}}